/* PhotoBridge v0.17.673 — lightweight photographer lab identity; no document-wide observer */
(()=>{
  const BAR_ID='pb673PhotographerLabIdentityBar',mq=window.matchMedia('(max-width:820px)');let timer=0;
  const clean=s=>String(s||'').replace(/\s+/g,' ').trim();
  function root(){return document.querySelector('.photographerMain.appWorkspacePage.pbFixedRoleHeader')}
  function labName(r){const selectors=['.photographerPrintTopLabStatic','.photographerMobileSingleLab span','.photographerSelectedLabNameButton b','.photographerLockedLabIdentity b','.photographerMobileLabChooser .pbSelectButton','.photographerMobileLabChooser button','.photographerPrintTopLabSelect .pbSelectButton','.photographerPrintTopLabSelect button'];for(const sel of selectors){const el=r?.querySelector(sel),t=clean(el?.textContent);if(t&&t!=='لابراتوار'&&t!=='انتخاب لابراتوار')return t.replace(/[⌄▾▼]+$/,'').trim()}return ''}
  function remove(r){document.getElementById(BAR_ID)?.remove();r?.classList.remove('pb673HasLabIdentityBar')}
  function sync(){timer=0;const r=root(),active=!!r&&mq.matches&&r.classList.contains('photographerLabWorkspaceMode');if(!active){remove(r);return}r.classList.add('pb673HasLabIdentityBar');let bar=document.getElementById(BAR_ID);if(!bar){bar=document.createElement('div');bar.id=BAR_ID;bar.setAttribute('aria-live','polite');bar.innerHTML='<span>لابراتوار</span><b></b>';document.body.appendChild(bar)}const name=labName(r)||'لابراتوار فعال',b=bar.querySelector('b');if(b&&b.textContent!==name)b.textContent=name;const h=r.querySelector(':scope > .unifiedRoleHeader.photographerHeaderRefined')||r.querySelector('.unifiedRoleHeader.photographerHeaderRefined');const bottom=Math.max(0,Math.ceil(h?.getBoundingClientRect().bottom||Number.parseFloat(getComputedStyle(r).getPropertyValue('--pb-role-header-h'))||64));if(bar.style.top!==bottom+'px')bar.style.top=bottom+'px'}
  function schedule(delay=50){clearTimeout(timer);timer=window.setTimeout(sync,delay)}
  const wrapHistory=name=>{const orig=history[name];if(typeof orig!=='function')return;history[name]=function(...args){const out=orig.apply(this,args);schedule(80);return out}};wrapHistory('pushState');wrapHistory('replaceState');
  window.addEventListener('popstate',()=>schedule(40));window.addEventListener('resize',()=>schedule(60),{passive:true});window.addEventListener('focus',()=>schedule(40),{passive:true});document.addEventListener('click',()=>schedule(90),{capture:true,passive:true});mq.addEventListener?.('change',()=>schedule(20));window.setInterval(()=>{if(!document.hidden)schedule(0)},1200);schedule(0);
})();
